// Parse fix request with input validation
const input = $input.item.json.body || $input.item.json;

// Validation functions to prevent shell injection
function validateAndSanitize(value, fieldName, pattern, maxLength = 500) {
  if (!value) return null;

  const str = String(value).trim();

  // Check length
  if (str.length > maxLength) {
    throw new Error(`${fieldName} exceeds maximum length of ${maxLength}`);
  }

  // Check against allowed pattern
  if (pattern && !pattern.test(str)) {
    throw new Error(`${fieldName} contains invalid characters`);
  }

  // Additional check: reject strings with shell metacharacters
  const dangerousChars = /[;&|`$(){}\[\]<>\n\r\\"']/;
  if (dangerousChars.test(str)) {
    throw new Error(`${fieldName} contains prohibited shell metacharacters`);
  }

  return str;
}

function validateRepoUrl(url) {
  if (!url) {
    throw new Error('repo_url is required');
  }

  const str = String(url).trim();

  // Allow only HTTPS git URLs with standard format
  const gitUrlPattern = /^https:\/\/[a-zA-Z0-9.-]+\/[a-zA-Z0-9._-]+\/[a-zA-Z0-9._-]+(\.git)?$/;
  if (!gitUrlPattern.test(str)) {
    throw new Error('repo_url must be a valid HTTPS git repository URL');
  }

  return str;
}

function validateBranch(branch) {
  if (!branch) return 'main';

  const str = String(branch).trim();

  // Git branch names: alphanumeric, hyphens, underscores, forward slashes, dots
  // But no shell metacharacters
  const branchPattern = /^[a-zA-Z0-9._/-]+$/;
  if (!branchPattern.test(str) || str.length > 255) {
    throw new Error('branch contains invalid characters or is too long');
  }

  // Reject branches that could be command injection attempts
  if (str.includes('..') || str.startsWith('-') || str.startsWith('/')) {
    throw new Error('branch name format is invalid');
  }

  return str;
}

function validateRequestId(requestId) {
  if (!requestId) {
    return `fix-${Date.now()}`;
  }

  const str = String(requestId).trim();

  // Allow only alphanumeric, hyphens, and underscores
  const requestIdPattern = /^[a-zA-Z0-9_-]+$/;
  if (!requestIdPattern.test(str) || str.length > 100) {
    throw new Error('request_id contains invalid characters or is too long');
  }

  return str;
}

function validateWorkDir(workDir) {
  if (!workDir) return null;

  const str = String(workDir).trim();

  // Work directory must be an absolute path under /tmp/cortex-fix/
  if (!str.startsWith('/tmp/cortex-fix/')) {
    throw new Error('work_dir must be under /tmp/cortex-fix/');
  }

  // Allow only safe path characters
  const pathPattern = /^\/tmp\/cortex-fix\/[a-zA-Z0-9._/-]+$/;
  if (!pathPattern.test(str) || str.length > 500) {
    throw new Error('work_dir contains invalid characters or is too long');
  }

  // Prevent path traversal
  if (str.includes('..') || str.includes('//')) {
    throw new Error('work_dir contains path traversal sequences');
  }

  return str;
}

// Validate and sanitize all inputs
try {
  const params = {
    repo_url: validateRepoUrl(input.repo_url),
    branch: validateBranch(input.branch),
    commit_sha: validateAndSanitize(input.commit_sha, 'commit_sha', /^[a-f0-9]{7,40}$/, 40),
    issues: typeof input.issues === 'string' ? JSON.parse(input.issues) : input.issues,
    work_dir: validateWorkDir(input.work_dir),
    create_pr: input.create_pr === true || input.create_pr === 'true',
    auto_merge: input.auto_merge === true,
    request_id: validateRequestId(input.request_id),
    fix_branch: `cortex/auto-fix-${Date.now()}`
  };

  // Extract repo info from validated URL
  const urlParts = params.repo_url.split('/');
  params.repo_name = urlParts[urlParts.length - 1].replace('.git', '');
  params.repo_owner = urlParts[urlParts.length - 2];

  // Determine what can be auto-fixed
  params.fixable = {
    lint: params.issues?.lint?.errors > 0 || params.issues?.lint?.warnings > 0,
    security: params.issues?.security?.high > 0 || params.issues?.security?.critical > 0
  };

  return [{
    json: {
      params: params,
      timestamp: new Date().toISOString()
    }
  }];
} catch (error) {
  // Return validation error
  throw new Error(`Input validation failed: ${error.message}`);
}

// Set work directory with validation
const params = $('Parse Request').item.json.params;
let workDir = params.work_dir;

if (!workDir || $('Has Work Dir?').item.json === false) {
  workDir = $input.item.json.stdout?.trim() || `/tmp/cortex-fix/${params.request_id}/repo`;
}

// Validate work directory again before use
function validateWorkDir(dir) {
  const str = String(dir).trim();

  // Must be under /tmp/cortex-fix/
  if (!str.startsWith('/tmp/cortex-fix/')) {
    throw new Error('work_dir must be under /tmp/cortex-fix/');
  }

  // Allow only safe path characters
  const pathPattern = /^\/tmp\/cortex-fix\/[a-zA-Z0-9._/-]+$/;
  if (!pathPattern.test(str) || str.length > 500) {
    throw new Error('work_dir contains invalid characters or is too long');
  }

  // Prevent path traversal
  if (str.includes('..') || str.includes('//')) {
    throw new Error('work_dir contains path traversal sequences');
  }

  return str;
}

workDir = validateWorkDir(workDir);

return [{
  json: {
    params: {...params, work_dir: workDir},
    work_dir: workDir
  }
}];

// Check if there are actual changes
const diffOutput = $input.item.json.stdout || '';
const hasChanges = diffOutput.trim().length > 0 && !diffOutput.includes('nothing to commit');

const context = $('Set Work Dir').item.json;

return [{
  json: {
    ...context,
    has_changes: hasChanges,
    diff_summary: diffOutput.trim()
  }
}];

// Prepare final result
const context = $('Evaluate Changes').item.json;
let prUrl = null;
let prNumber = null;

try {
  const prResponse = $('Create PR').item?.json;
  prUrl = prResponse?.html_url;
  prNumber = prResponse?.number;
} catch (e) { /* no PR created */ }

return [{
  json: {
    success: true,
    request_id: context.params.request_id,
    repo: context.params.repo_url,
    branch: context.params.branch,
    fix_branch: context.params.fix_branch,
    changes_applied: context.has_changes,
    diff_summary: context.diff_summary,
    pr_created: prUrl !== null,
    pr_url: prUrl,
    pr_number: prNumber,
    timestamp: new Date().toISOString()
  }
}];

// No changes result
const context = $('Evaluate Changes').item.json;

return [{
  json: {
    success: true,
    request_id: context.params.request_id,
    repo: context.params.repo_url,
    changes_applied: false,
    message: 'No fixable issues found or all issues require manual intervention',
    timestamp: new Date().toISOString()
  }
}];
